create table public.account_recovery(username text primary key,user_id uuid not null unique references auth.users(id) on delete cascade,code_hash text not null); alter table public.account_recovery enable row level security; revoke all on public.account_recovery from anon,authenticated; grant all on public.account_recovery to service_role; create table public.account_attempts(key text not null,bucket timestamptz not null,requests integer not null default 1,primary key(key,bucket)); alter table public.account_attempts enable row level security; revoke all on public.account_attempts from anon,authenticated; grant all on public.account_attempts to service_role; create function public.consume_account_attempt(p_key text) returns boolean language plpgsql security invoker set search_path='' as $$ declare n int; begin insert into public.account_attempts(key,bucket,requests) values(p_key,date_trunc('hour',now()),1) on conflict(key,bucket) do update set requests=account_attempts.requests+1 returning requests into n; return n<=10; end $$; revoke all on function public.consume_account_attempt(text) from public,anon,authenticated; grant execute on function public.consume_account_attempt(text) to service_role;
